const COPPER = '#d69771';
const SILVER = '#aba7a8';
const BLUISH = '#456FA1';
const GOLD = '#c7a24a';

export class StarfleetAcademyUniformPack
  extends BaseTngEraUniformPack
  implements IUniformPack
{
  constructor() {
    super(UniformEra.StarfleetAcademy);
  }

  protected getCadetRankSwatches() {
    return [
      new Swatch(
        Rank.CadetFirstClass,
        'Cadet 1st Class',
        (token) =>
          RankIndicatorCatalog.decorateSwatch(
            CollarPips.CadetFourthClass,
            Rank.CadetFirstClass,
            token,
          ),
        'Rank.cadetFirstClass.name',
      ),
      new Swatch(
        Rank.CadetSecondClass,
        'Cadet 2nd Class',
        (token) =>
          RankIndicatorCatalog.decorateSwatch(
            CollarPips.CadetThirdClass,
            Rank.CadetSecondClass,
            token,
          ),
        'Rank.cadetSecondClass.name',
      ),
      new Swatch(
        Rank.CadetThirdClass,
        'Cadet 3rd Class',
        (token) =>
          RankIndicatorCatalog.decorateSwatch(
            CollarPips.CadetSecondClass,
            Rank.CadetThirdClass,
            token,
          ),
        'Rank.cadetThirdClass.name',
      ),
      new Swatch(
        Rank.CadetFourthClass,
        'Cadet 4th Class',
        (token) =>
          RankIndicatorCatalog.decorateSwatch(
            CollarPips.CadetFirstClass,
            Rank.CadetFourthClass,
            token,
          ),
        'Rank.cadetFourthClass.name',
      ),
    ];
  }

  getUniformSwatches() {
    return [
      new Swatch(
        BodyType.AverageMale,
        'Average Male',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Base,
              BodyType.AverageMale,
            ),
            BodyType.AverageMale,
            token,
          ),
        'BodyType.averageMale',
      ),
      new Swatch(
        BodyType.AverageFemale,
        'Average Female',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Base,
              BodyType.AverageFemale,
            ),
            BodyType.AverageFemale,
            token,
          ),
        'BodyType.averageFemale',
      ),
    ];
  }

  getUniformVariantSwatches(token: TokenModel) {
    if (isCadetRank(token.rankIndicator)) {
      return [];
    } else {
      const variants = [
        new Swatch(UniformVariantType.Base, 'Base', (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Base,
              token.bodyType,
            ),
            UniformVariantType.Base,
            token,
          ),
        ),
        new Swatch(UniformVariantType.Variant1, 'Grey Variant', (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Variant1,
              token.bodyType,
            ),
            UniformVariantType.Variant1,
            token,
          ),
        ),
      ];
      variants.push(
        new Swatch(UniformVariantType.Variant2, 'Academy Instructor', (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Variant2,
              token.bodyType,
            ),
            UniformVariantType.Variant2,
            token,
          ),
        ),
      );

      return variants;
    }
  }

  getUniformAndVariantBody(token: TokenModel) {
    return this.getUniformAndVariantByBodyType(
      token,
      token.variant,
      token.bodyType,
    );
  }

  getUniformAndVariantByBodyType(
    token: TokenModel,
    variant: UniformVariantType,
    bodyType: BodyType,
  ) {
    let base = '';
    const divisionColour = token.divisionColor;
    if (isCadetRank(token.rankIndicator)) {
      if (bodyType === BodyType.AverageMale) {
        base = StarfleetAcademyUniform.maleBodyCadetVariant;
      } else {
        base = StarfleetAcademyUniform.femaleBodyCadetVariant;
      }
    } else {
      if (bodyType === BodyType.AverageMale) {
        if (variant === UniformVariantType.Variant2) {
          base = StarfleetAcademyUniform.maleBodyInstructorVariant;
        } else {
          base = StarfleetAcademyUniform.maleBody;
        }
      } else {
        if (variant === UniformVariantType.Variant2) {
          base = StarfleetAcademyUniform.femaleBodyInstructorVariant;
        } else {
          base = StarfleetAcademyUniform.femaleBody;
        }
      }
      if (
        token.rankIndicator === Rank.Captain &&
        [UniformVariantType.Base, UniformVariantType.Variant1].includes(variant)
      ) {
        if (bodyType === BodyType.AverageMale) {
          base += StarfleetAcademyUniform.maleBodyCaptainsVariant;
        } else {
          base += StarfleetAcademyUniform.femaleBodyCaptainsVariant;
        }
      }
    }

    if (variant === UniformVariantType.Variant1) {
      base = base
        .replace(DefaultRed, '#808889')
        .replace(/#2c2c2c/g, divisionColour)
        .replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
    } else {
      base = base
        .replace(DefaultRed, divisionColour)
        .replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
    }
    let metalHighlights = COPPER;
    if (
      DivisionColors.getDivision(this.era, token.divisionColor) === 'Command'
    ) {
      metalHighlights = COPPER;
    } else if (
      DivisionColors.getDivision(this.era, token.divisionColor) === 'Science'
    ) {
      metalHighlights = BLUISH;
    } else if (
      DivisionColors.getDivision(this.era, token.divisionColor) === 'Operations'
    ) {
      metalHighlights = GOLD;
    } else if (
      DivisionColors.getDivision(this.era, token.divisionColor) === 'Medical'
    ) {
      metalHighlights = SILVER;
    }

    base = base.replace(/#d69771/g, metalHighlights);

    return (
      this.getNeck(
        bodyType,
        token.skinColor,
        token.species,
        UniformEra.DominionWar,
      ) + base
    );
  }

  getRankIndicator(token: TokenModel) {
    return '';
  }

  getBorderLogo(token: TokenModel): string {
    if (isCadetRank(token.rankIndicator)) {
      return cadetBorderInsignia.replace(DefaultRed, token.divisionColor);
    } else {
      return borderInsignia;
    }
  }

  getBorderColor(token: TokenModel): string {
    return token.divisionColor;
  }

  getRankBorderIndicator(token: TokenModel): string {
    return rankIndicators.border[Rank[token.rankIndicator]] ?? '';
  }
}
